'use strict';
// UBX-V3, Etapa 5 — caracterização do cadastro de EPI
// (modules/epis/{business,ui} e modules/shared/ui/file-data-url.js).
//
// O MESMO roteiro roda sobre as funções ORIGINAIS do app.js (geração das
// tabelas, commit da Etapa 4, antes da extração) e sobre os módulos, com DOM
// falso e espiões. Ficam fixados: fluxos de foto (sem arquivo, não imagem,
// sucesso, erro), captura de câmera, escopo "Todas as Unidades" por perfil,
// unidade operacional, trava por Joint Venture, edição, preparo dos valores
// enviados (JV, Todas as Unidades, tamanhos, foto ao editar), reset, linha da
// tabela e rótulo do seletor. fileToDataUrl/fileToJpegDataUrl (FileReader,
// Image, canvas) foram comparados no Chromium real (docs §11).
const fs = require('fs'), path = require('path'), vm = require('vm');
const JS_ROOT = path.resolve(__dirname, '..');
const MODULES = ['modules/shared/ui/file-data-url.js', 'modules/epis/business/epi-form-values.js',
  'modules/epis/ui/epi-registration.js'];
const UI = ['renderEpiPhotoPreview', 'handleEpiPhotoUpload', 'openEpiPhotoPicker', 'configureEpiPhotoInputCapture',
  'canUseEpiAllUnitsScope', 'syncEpiUnitOptions', 'applyEpiJoinventureRules', 'startEditEpi', 'setEpiPhotoData',
  'prepareEpiFormValues', 'resetEpiForm', 'buildEpiRow'];
const BUSINESS = ['normalizeEpiSizes', 'formatEpiOptionLabel'];
const ALL = 'ALLX';

function makeEnv() {
  const log = [];
  const node = (id, extra = {}) => ({
    id, value: '', innerHTML: '', textContent: '', disabled: false, attrs: {}, files: [], options: [],
    setAttribute(k, v) { this.attrs[k] = v; log.push(['setAttribute', id, k, v]); },
    removeAttribute(k) { delete this.attrs[k]; log.push(['removeAttribute', id, k]); },
    click() { log.push(['click', id]); },
    ...extra
  });
  const ids = ['epi-photo-preview', 'epi-photo-data', 'epi-photo-file', 'epi-company', 'epi-unit', 'epi-joinventure-active',
    'epi-unit-rule-hint', 'epi-joinventures'];
  const nodes = Object.fromEntries(ids.map((id) => [id, node(id)]));
  const fieldNames = ['id', 'company_id', 'unit_id', 'name', 'purchase_code', 'ca', 'sector', 'epi_section', 'model_reference',
    'manufacturer', 'supplier_company', 'unit_measure', 'ca_expiry', 'epi_validity_date', 'glove_size', 'size', 'uniform_size',
    'manufacturer_validity_months', 'manufacturer_recommendations', 'epi_photo_data', 'active_joinventure'];
  const elements = Object.fromEntries(fieldNames.map((n) => [n, node(`f:${n}`)]));
  elements.unit_id.options = [{ value: '5' }, { value: '6' }];
  const form = { elements };
  const state = {
    user: { id: 1, role: 'general_admin', company_id: 901, operational_unit_id: '' },
    units: [{ id: 5, company_id: 901, name: 'Base A', unit_type: 'base' }, { id: 6, company_id: 901, name: 'Navio B', unit_type: 'navio' },
      { id: 7, company_id: 902, name: 'Outra', unit_type: 'base' }],
    epis: [{ id: 40, company_id: 901, unit_id: 6, name: 'Luva', purchase_code: 'L1', ca: '123', sector: '', epi_section: 'Mãos',
      model_reference: 'M', manufacturer: 'Danny', supplier_company: 'ACME', unit_measure: '', ca_expiry: '2027-01-01',
      epi_validity_date: '', glove_size: 'M', size: null, uniform_size: undefined, manufacturer_validity_months: undefined,
      validity_months: 12, manufacturer_recommendations: 'Lavar', epi_photo_data: 'data:img', joinventures_json: '[{"name":"JV1"}]',
      active_joinventure: 'JV1' }]
  };
  const env = {
    log, nodes, elements, form, state, operational: false, mobile: false, jpegResult: 'data:image/jpeg;x',
    globals: {
      Promise, JSON, Object, Array, String, Number, Error,
      document: { getElementById: (id) => (id === 'epi-form' ? (env.noForm ? null : form) : nodes[id] || null) },
      tr: (_k, fallback) => fallback,
      alert: (m) => log.push(['alert', m]),
      isMobileUserAgent: () => env.mobile,
      isOperationalProfile: () => env.operational,
      filterByUserCompany: (items) => (items || []).filter((i) => i.company_id === 901),
      unitTypeLabel: (t) => `T(${t})`,
      EPI_ALL_UNITS_VALUE: ALL,
      EPI_ALL_UNITS_PROFILES: Object.freeze(['general_admin', 'registry_admin']),
      parseActiveJoinventureToken: (v) => { const [name, unit] = String(v || '').split('::'); return { name: name || '', unit_id: unit || '' }; },
      renderJoinventureList: () => log.push(['renderJoinventureList']),
      currentJoinventures: () => [{ name: 'JV1', unit_id: 6 }],
      activeJoinventureToken: (e) => `${e.name}::${e.unit_id}`,
      setFormSubmitLabel: (id, text) => log.push(['setFormSubmitLabel', id, text]),
      showView: (v) => log.push(['showView', v]),
      setEpiValidity: (values) => { log.push(['setEpiValidity']); values.validity_set = true; },
      epiProtectionLabel: (v) => `P(${v})`,
      epiMeasureLabel: (v) => `M(${v})`,
      fileToJpegDataUrl: async (file, width) => { log.push(['fileToJpegDataUrl', file.name, width]); if (env.jpegFails) { throw new Error(env.jpegFails); } return env.jpegResult; },
      fileToDataUrl: async (file) => { log.push(['fileToDataUrl', file.name]); return `data:raw:${file.name}`; }
    }
  };
  return env;
}

function contextFor(env) {
  const ctx = vm.createContext({ ...env.globals, state: env.state, __EPI_APP_STATE__: env.state });
  ctx.globalThis = ctx;
  return ctx;
}

function snapshot(env) {
  const pick = (o) => Object.fromEntries(Object.entries(o).map(([k, n]) => [k, [n.value, n.innerHTML, n.textContent, n.disabled, n.attrs]]));
  return { nodes: pick(env.nodes), fields: pick(env.elements), log: env.log.splice(0) };
}

async function scenario(run) {
  const out = {};
  const go = async (prep, act) => { const env = makeEnv(); prep(env); const fns = run(env); const r = await act(fns, env); return { r, ...snapshot(env) }; };
  const none = () => {};

  out.preview = await go(none, (f, env) => { f.renderEpiPhotoPreview(''); const vazio = env.nodes['epi-photo-preview'].innerHTML; f.renderEpiPhotoPreview('data:x'); return vazio; });
  out.uploadSemArquivo = await go(none, (f, env) => f.handleEpiPhotoUpload({ target: env.nodes['epi-photo-file'] }));
  out.uploadNaoImagem = await go(none, (f, env) => { env.nodes['epi-photo-file'].files = [{ name: 'a.pdf', type: 'application/pdf' }]; env.nodes['epi-photo-file'].value = 'C:/a.pdf'; return f.handleEpiPhotoUpload({ target: env.nodes['epi-photo-file'] }); });
  out.uploadOk = await go(none, (f, env) => { env.nodes['epi-photo-file'].files = [{ name: 'f.png', type: 'image/png' }]; return f.handleEpiPhotoUpload({ target: env.nodes['epi-photo-file'] }); });
  out.uploadErro = await go((env) => { env.jpegFails = 'falhou'; }, (f, env) => { env.nodes['epi-photo-file'].files = [{ name: 'f.png', type: 'image/png' }]; return f.handleEpiPhotoUpload({ target: env.nodes['epi-photo-file'] }); });
  out.uploadErroSemMsg = await go((env) => { env.jpegFails = ''; }, (f, env) => { env.nodes['epi-photo-file'].files = [{ name: 'f.png', type: 'image/png' }]; return f.handleEpiPhotoUpload({ target: env.nodes['epi-photo-file'] }); });
  out.uploadSemCampo = await go((env) => { delete env.nodes['epi-photo-data']; }, (f, env) => f.handleEpiPhotoUpload({ target: env.nodes['epi-photo-file'] }));
  out.pickerDesktop = await go(none, (f) => f.openEpiPhotoPicker({ preferCamera: true }));
  out.pickerMobile = await go((env) => { env.mobile = true; }, (f) => { f.openEpiPhotoPicker({ preferCamera: true }); f.openEpiPhotoPicker(); f.openEpiPhotoPicker({ preferCamera: false }); });
  out.capture = await go((env) => { env.mobile = true; }, (f) => f.configureEpiPhotoInputCapture());
  out.captureDesktop = await go(none, (f) => f.configureEpiPhotoInputCapture());
  out.escopo = await go(none, (f, env) => ['general_admin', 'registry_admin', 'admin', 'operator', undefined].map((role) => { env.state.user.role = role; return f.canUseEpiAllUnitsScope(); }));

  out.syncLivre = await go(none, (f) => f.syncEpiUnitOptions());
  out.syncAnterior = await go((env) => { env.nodes['epi-unit'].value = '6'; env.state.user.role = 'admin'; }, (f) => f.syncEpiUnitOptions());
  out.syncSemTodas = await go((env) => { env.state.user.role = 'admin'; }, (f) => f.syncEpiUnitOptions());
  out.syncOperacional = await go((env) => { env.operational = true; env.state.user.operational_unit_id = '6'; }, (f) => f.syncEpiUnitOptions());
  out.syncOperacionalSemUnidade = await go((env) => { env.operational = true; }, (f) => f.syncEpiUnitOptions());
  out.syncEmpresaVazia = await go((env) => { env.state.user.company_id = null; env.nodes['epi-company'].value = '902'; env.state.user.role = 'admin'; }, (f) => f.syncEpiUnitOptions());
  out.jvAtiva = await go((env) => { env.nodes['epi-joinventure-active'].value = 'JV1::6'; }, (f) => f.applyEpiJoinventureRules());
  out.jvInativa = await go(none, (f) => f.applyEpiJoinventureRules());
  out.jvSemHint = await go((env) => { delete env.nodes['epi-unit-rule-hint']; env.operational = true; }, (f) => f.applyEpiJoinventureRules());

  out.editar = await go(none, (f) => f.startEditEpi(40));
  out.editarInexistente = await go(none, (f) => f.startEditEpi(99));
  out.prepararJv = await go(none, (f) => f.prepareEpiFormValues({ active_joinventure: 'JV1::6', unit_id: ALL, epi_photo_data: '' }, '', {}));
  out.prepararTodas = await go(none, (f) => f.prepareEpiFormValues({ active_joinventure: '', unit_id: ALL, glove_size: 'G', epi_photo_data: 'x' }, '40', {}));
  out.prepararEdicaoSemFoto = await go(none, (f) => f.prepareEpiFormValues({ unit_id: '5' }, '40', {}));
  out.prepararEdicaoComArquivo = await go((env) => { env.nodes['epi-photo-file'].files = [{ name: 'nova.png' }]; }, (f) => f.prepareEpiFormValues({ unit_id: '5' }, '40', {}));
  out.prepararNovoSemFoto = await go(none, (f) => f.prepareEpiFormValues({ unit_id: '5' }, '', {}));
  out.fotoEdicaoInexistente = await go(none, async (f) => { const v = {}; await f.setEpiPhotoData(v, '99'); return v; });
  out.reset = await go(none, (f, env) => f.resetEpiForm(env.form));
  out.resetSemTodas = await go((env) => { env.state.user.role = 'operator'; }, (f, env) => f.resetEpiForm(env.form));
  out.linhas = await go(none, (f) => [
    f.buildEpiRow({ id: 1, company_name: 'C', scope_label: 'Escopo', name: 'N', purchase_code: 'P', sector: 's', unit_measure: 'par' }, true),
    f.buildEpiRow({ id: 2, company_name: 'C', scope_type: 'global', name: 'N', purchase_code: 'P' }, false),
    f.buildEpiRow({ id: 3, company_name: 'C', unit_name: 'U', is_joint_venture: '1', name: 'N', purchase_code: 'P', manufacturer: 'F', active_joinventure: 'JV' }, true),
    f.buildEpiRow({ id: 4 }, false)
  ]);
  out.negocio = await go(none, (f) => {
    const values = { glove_size: '', size: 0, uniform_size: 'GG' };
    f.normalizeEpiSizes(values);
    return [values, [{ name: 'Luva', glove_size: 'M', size: 'N/A', uniform_size: '', manufacturer: 'Danny', unit_measure: 'par' },
      { name: 'Bota', size: '42', unit_measure: 'unidade' }, {}].map((i) => f.formatEpiOptionLabel(i))];
  });
  return out;
}

