function loadModules(env, { realFileHelpers = false } = {}) {
  const ctx = contextFor(env);
  for (const rel of MODULES) { vm.runInContext(fs.readFileSync(path.join(JS_ROOT, rel), 'utf8'), ctx); }
  if (!realFileHelpers) {
    // FileReader/Image/canvas não existem no Node: no roteiro, as duas leituras
    // de arquivo são espiões (como na geração a partir das originais); o
    // comportamento real delas foi comparado no Chromium.
    ctx.fileToDataUrl = env.globals.fileToDataUrl;
    ctx.fileToJpegDataUrl = env.globals.fileToJpegDataUrl;
  }
  return ctx;
}

module.exports = function ({ testAsync, test, assert, eq }) {
  testAsync('UBX-V3 EPIs: os módulos reproduzem as funções originais do cadastro', async () => {
    const actual = await scenario(loadModules);
    for (const key of Object.keys(EXPECTED)) {
      eq(JSON.stringify(actual[key]), JSON.stringify(EXPECTED[key]), key);
    }
    eq(Object.keys(actual).sort().join(','), Object.keys(EXPECTED).sort().join(','));
  });

  test('UBX-V3 EPIs: nomes globais, namespaces, camadas e ordem de carga', () => {
    const ctx = loadModules(makeEnv(), { realFileHelpers: true });
    for (const name of [...UI, ...BUSINESS, 'fileToDataUrl', 'fileToJpegDataUrl']) { eq(typeof ctx[name], 'function', name); }
    for (const ns of ['__EPI_EPIS_VIEW__', '__EPI_EPIS_BUSINESS__', '__EPI_SHARED_FILE_DATA_URL__']) {
      assert(Object.isFrozen(ctx[ns]), `${ns} congelado`);
    }
    const scripts = fs.readFileSync(path.resolve(JS_ROOT, '..', 'views', '_scripts.html'), 'utf8');
    const order = [...scripts.matchAll(/<script[^>]+src="([^"?]+)/g)].map((m) => m[1]);
    const idx = MODULES.map((m) => order.indexOf(`/js/${m}`));
    assert(idx.every((i) => i >= 0) && idx[0] < idx[1] && idx[1] < idx[2], 'arquivo → negócio → UI');
    assert(idx[2] < order.indexOf('/app.js'), 'antes do app.js');
    assert(order.indexOf('/js/core/constants.js') < idx[2], 'core/constants.js (EPI_ALL_UNITS_*) antes da UI');
    const app = fs.readFileSync(path.resolve(JS_ROOT, '..', 'app.js'), 'utf8');
    for (const name of [...UI, ...BUSINESS, 'fileToDataUrl', 'fileToJpegDataUrl']) {
      assert(!new RegExp(`^(?:async\\s+)?function\\s+${name}\\(`, 'm').test(app), `${name} voltou ao app.js`);
    }
    const constants = fs.readFileSync(path.join(JS_ROOT, 'core', 'constants.js'), 'utf8');
    assert(constants.includes("const EPI_ALL_UNITS_VALUE = '__ALL_UNITS__';") && app.includes("const EPI_ALL_UNITS_VALUE = '__ALL_UNITS__';"),
      'EPI_ALL_UNITS_VALUE igual no app.js e em core/constants.js');
    assert(constants.includes("const EPI_ALL_UNITS_PROFILES = Object.freeze(['general_admin', 'registry_admin']);")
      && app.includes("const EPI_ALL_UNITS_PROFILES = Object.freeze(['general_admin', 'registry_admin']);"),
    'EPI_ALL_UNITS_PROFILES igual no app.js e em core/constants.js');
  });
};

module.exports.scenario = scenario;
module.exports.contextFor = contextFor;
